import org.junit.jupiter.api.Test;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertEquals;

class VueGeneratorMutaGate4Test {

    @Test
    void testIdJoinsModuleAndSuffixWithSingleHyphen() throws Exception {
        ModuleSpec spec = SpecLoader.load(Path.of("examples/project.yaml"));
        String module = spec.module();

        // Suffix is appended verbatim after exactly one hyphen
        assertEquals(module + "-add-btn", VueGenerator.testId(spec, "add-btn"));
        assertEquals(module + "-a-b_C d", VueGenerator.testId(spec, "a-b_C d"));
        // Empty suffix still yields the separator
        assertEquals(module + "-", VueGenerator.testId(spec, ""));

        // Not trimmed or case-altered
        assertEquals(module + "-Table", VueGenerator.testId(spec, "Table"));

        // Consistent with the field anchor convention
        FieldSpec f = spec.fields().get(0);
        assertEquals(
                VueGenerator.fieldTestId(spec, f),
                VueGenerator.testId(spec, VueGenerator.kebab(f.name()) + "-input"));
    }
}

