import static org.junit.jupiter.api.Assertions.assertEquals;

class VueGeneratorMutaGate5Test {

    private static FieldSpec field(String name, FieldType type) {
        return new FieldSpec(name, "col", type, null, null, null, true, "c",
                FieldSpec.QueryMode.NONE, false);
    }

    @Test
    void fieldTestIdKebabCasesNameWithModulePrefixAndInputSuffix() throws Exception {
        ModuleSpec spec = SpecLoader.load(Path.of("examples/project.yaml"));
        String prefix = spec.module() + "-";

        // no uppercase: unchanged
        assertEquals(prefix + "name-input",
                VueGenerator.fieldTestId(spec, field("name", FieldType.STRING)));
        // consecutive uppercase letters each get their own hyphen
        assertEquals(prefix + "user-i-d-input",
                VueGenerator.fieldTestId(spec, field("userID", FieldType.LONG)));
        // leading uppercase yields a leading hyphen
        assertEquals(prefix + "-name-input",
                VueGenerator.fieldTestId(spec, field("Name", FieldType.STRING)));
        // digits are kept as-is; field type does not influence the id
        assertEquals(prefix + "addr2-line-input",
                VueGenerator.fieldTestId(spec, field("addr2Line", FieldType.FLAG)));
    }
}

package io.github.describeadmin.codegen.generator;

import io.github.describeadmin.codegen.model.ModuleSpec;
import io.github.describeadmin.codegen.parser.SpecLoader;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertEquals;

class VueGeneratorMutaGate6Test {

    private static ModuleSpec withPrefix(ModuleSpec base, String prefix) {
        return new ModuleSpec(
                base.basePackage(),
                base.module(),
                base.entity(),
                base.table(),
                base.comment(),
                prefix,
                base.layout(),
                base.layoutOrigin(),
                base.fields());
    }

    @Test
    void clientPathStripsOnlyLeadingApiPrefixOnce() throws Exception {
        ModuleSpec base = SpecLoader.load(Path.of("examples/project.yaml"));

        // 开头的 /api 被去掉，其余保留
        assertEquals("/project", VueGenerator.clientPath(withPrefix(base, "/api/project")));
        assertEquals("/sys/user", VueGenerator.clientPath(withPrefix(base, "/api/sys/user")));

        // 只去掉第一次出现的前缀，不会递归剥离
        assertEquals("/api/x", VueGenerator.clientPath(withPrefix(base, "/api/api/x")));

        // 不在开头的 api 不动
        assertEquals("/v1/api/project", VueGenerator.clientPath(withPrefix(base, "/v1/api/project")));

        // 没有 /api 前缀的路径原样返回
        assertEquals("/project", VueGenerator.clientPath(withPrefix(base, "/project")));
    }
}

