import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class VueGeneratorMutaGate8Test {

    private static String ts(FieldType t) {
        return switch (t) {
            case STRING, TEXT, DATE, DATETIME, LONG -> "string";
            case INT, DECIMAL, FLAG -> "number";
        };
    }

    private static String block(String text, String startMarker) {
        int start = text.indexOf(startMarker);
        assertTrue(start >= 0, "missing: " + startMarker);
        start += startMarker.length();
        int end = text.indexOf("\n}\n", start);
        assertTrue(end >= start, "unterminated block: " + startMarker);
        return text.substring(start, end);
    }

    @Test
    void apiInterfacesAreSortedAndComplete() throws Exception {
        ModuleSpec spec = SpecLoader.load(Path.of("examples/project.yaml"));
        String api = VueGenerator.api(spec);
        String e = spec.entity();

        // header carries the module comment
        assertTrue(api.startsWith("/**\n * " + spec.comment() + " 接口。由 codegen 生成。\n"));

        // entity interface: one line per field, sorted
        List<String> expectedFields = new ArrayList<>();
        for (FieldSpec f : spec.fields()) {
            expectedFields.add("  " + f.name() + "?: " + ts(f.type()) + ";");
        }
        Collections.sort(expectedFields);
        String entityBody = block(api, "export interface " + e + " extends " + e + "Audit {\n");
        assertEquals(String.join("\n", expectedFields), entityBody);

        // query interface: paging first, then sorted query lines (range split into Start/End)
        List<String> expectedQuery = new ArrayList<>();
        for (FieldSpec f : spec.queryFields()) {
            if (f.query() == FieldSpec.QueryMode.RANGE) {
                expectedQuery.add("  " + f.name() + "End?: " + ts(f.type()) + ";");
                expectedQuery.add("  " + f.name() + "Start?: " + ts(f.type()) + ";");
            } else {
                expectedQuery.add("  " + f.name() + "?: " + ts(f.type()) + ";");
            }
        }
        Collections.sort(expectedQuery);
        String queryBody = block(api,
                "export interface " + e + "Query {\n  current?: number;\n  size?: number;\n");
        assertEquals(String.join("\n", expectedQuery), queryBody);

        // function signatures wired to the entity name
        assertTrue(api.contains("export async function get" + e + "ListApi(params: " + e + "Query)"));
        assertTrue(api.contains("export async function create" + e + "Api(data: " + e + ")"));
        assertTrue(api.contains("export async function update" + e + "Api(id: string, data: " + e + ")"));
        assertTrue(api.contains("requestClient.put<" + e + ">(`"));
        assertTrue(api.contains("export interface " + e + "Page {"));
        assertTrue(api.contains("records: " + e + "[];"));
    }
}
